def definir_andar_padrao(apps, schema_editor):
    """Quadros que já existiam vão para o 1º andar."""
    Andar = apps.get_model("usuarios", "Andar")
    Quadro = apps.get_model("kanban", "Quadro")
    primeiro = Andar.objects.order_by("numero").first()
    if primeiro:
        Quadro.objects.filter(andar__isnull=True).update(andar=primeiro)


